	title 'Integer      Math         GS ROM 3.0'*********************************************************		               **                Integer Math	               **		               ******************************************************************************************************************		               **              Copyright (C) 1985-1989	               **              Apple Computer, Inc.	               **              All Rights Reserved	               **		               ********************************************************************************************************************************* Change History** 30 Mar 89	Steven Glass** Fixed bug in Long2Dec************************************************************************	include 'all.macros'****************************************************************** INTEGER MATH TOOLS MAIN CODE SEGMENT*****************************************************************IMVerNum	equ $0300	;Version 3.0****************************************************************** DATA*****************************************************************BadParam	equ $0B01BadChar	equ $0B02Overflow	equ $0B03ShortStr	equ $0B04;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall10	IMPORT EndCall12	IMPORT EndCall4	IMPORT EndCall6	IMPORT EndCall8	IMPORT ErrOut10	IMPORT ErrOut12	IMPORT ErrOut4	IMPORT ErrOut6	IMPORT ErrOut8	IMPORT oEndCall0	IMPORT oEndCall2	IMPORT oErrOut0;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY Bin2Hex	ENTRY Dec2Bin	ENTRY Dec2Int	ENTRY Dec2Long	ENTRY Fix2Frac	ENTRY Fix2Long	ENTRY Fix2X	ENTRY FixATan2	ENTRY FixDiv	ENTRY FixMul	ENTRY FixRatio	ENTRY FixRound	ENTRY Frac2Fix	ENTRY Frac2X	ENTRY FracCos	ENTRY FracDiv	ENTRY FracMul	ENTRY FracSin	ENTRY FracSqrt	ENTRY Hex2Bin	ENTRY Hex2Int	ENTRY Hex2Long	ENTRY HexIt	ENTRY HiWord	ENTRY IMActive	ENTRY IMVersion	ENTRY Int2Dec	ENTRY Int2Hex	ENTRY LoWord	ENTRY Long2Dec	ENTRY Long2Fix	ENTRY Long2Hex	ENTRY LongDiv	ENTRY LongMul	ENTRY Multiply	ENTRY SDivide	ENTRY UDIV	ENTRY UDivide	ENTRY X2Fix	ENTRY X2Frac****************************************************************** CALL TABLE*****************************************************************	EXPORT IMCallTableIMCallTable	PROC	DC.L (TheEnd-IMCallTable)/4	DC.L oEndCall0-1	;power up init	DC.L oEndCall0-1	;application startup	DC.L oEndCall0-1	;application shutdown	DC.L IMVersion-1	DC.L oEndCall0-1	;reset	DC.L IMActive-1	DC.L oEndCall0-1	;reserved	DC.L oEndCall0-1	;reserved	DC.L Multiply-1	DC.L SDivide-1	DC.L UDivide-1	DC.L LongMul-1	DC.L LongDiv-1	DC.L FixRatio-1	DC.L FixMul-1	DC.L FracMul-1	DC.L FixDiv-1	DC.L FracDiv-1	DC.L FixRound-1	DC.L FracSqrt-1	DC.L FracCos-1	DC.L FracSin-1	DC.L FixATan2-1	DC.L HiWord-1	DC.L LoWord-1	DC.L Long2Fix-1	DC.L Fix2Long-1	DC.L Fix2Frac-1	DC.L Frac2Fix-1	DC.L Fix2X-1	DC.L Frac2X-1	DC.L X2Fix-1	DC.L X2Frac-1	DC.L Int2Hex-1	DC.L Long2Hex-1	DC.L Hex2Int-1	DC.L Hex2Long-1	DC.L Int2Dec-1	DC.L Long2Dec-1	DC.L Dec2Int-1	DC.L Dec2Long-1	DC.L HexIt-1TheEnd		; 	ENDP****************************************************************** NotYet*****************************************************************	EXPORT NotYetNotYet	PROC	ldx #$FFFF	jmp oErrOut0	ENDP****************************************************************** IMVersion*****************************************************************	EXPORT IMVersionIMVersion	PROC	lda #IMVerNum	sta 7,s	jmp oEndCall0	ENDP****************************************************************** IMActive*****************************************************************	EXPORT IMActiveIMActive	PROC	lda #$FFFF	sta 7,s	jmp oEndCall0	ENDP;                copy intmath/math****************************************************************** Multiply** Multiplies two values on the stack.** Low word is the signed result of multiplication.* Two words together is the unsigned 32	bit result.** The stack looks like this on input:**      Result	 8-B*      M1	 6-7*      M2	 4-5*      Return	 1-3** Change History:** January 28, 1987	  Steven Glass**      New algoithm	using a-reg instead	of direct page for*      holding high	word of result saves lots of cycles.*      Thanks to Chris Jewell for the suggestion and Jim Merrit*      for forewarding it.** February 10, 1987	  Steven Glass, Fern Bachman, Mike Askins**      Chris's algorithmn did not work.  We made it work.*****************************************************************	EXPORT MultiplyMultiply	PROCDReg	equ 1	; 1RTL1	equ DReg+2	; 3RTL2	equ RTL1+3	; 6M2	equ RTL2+3	; 9M1	equ M2+2	; BResult	equ M1+2	; D	phd	; save direct	tsc	; make stack into zp	tcd	lda M2	; move second input	into	sta Result	; result	lda #0	; zero a-reg	ldy #17	; start y (our counter and 17)	clcMult1		; 	ror a	ror Result	bcc Mult2	clc	adc M1Mult2		; 	dey	bne Mult1	sta Result+2	jmp EndCall4	ENDP****************************************************************** UDivide** Divides one 16 bit value by another and returns a dividend* and remainder.** Inputs and result	are passed on the stack.** The stack on entry is as follows:**      Remainder	10-11*      Quotient	8-9*      Numerator	6-7*      Denom	4-5*      Return	1-3** This routine sets	up the stack, moves	the pointer to x.* sets the data bank register to 0 and calls UDIV*****************************************************************	EXPORT UDivideUDivide	PROC	phd	tsc	tcd	jsl UDIV	bcs UDivErr	jmp EndCall4UDivErr		; 	ldx #BadParam	; input parm error	jmp ErrOut4	ENDP****************************************************************** SDivide** Divides one 16 bit value by another and returns a dividend* and remainder.** Inputs and result	are passed on the stack.** The stack on entry is as follows:**      Remainder	10-11*      Quotient	8-9*      Numerator	6-7*      Denom	4-5*      Return	1-3** This routine sets	up the stack, moves	the pointer to x.* sets the data bank register to 0 and calls UDIV** Change History** 9 Feb 87     Steven Glass**       The error exit path now cleans up the stack.*****************************************************************	EXPORT SDivideSDivide	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Denom	equ RTL2+3Numerator	equ Denom+2Quotient	equ Numerator+2Remainder	equ Quotient+2	phd	tsc	tcd** Figure out the signs of the results:	Remainder is always	the* same sign as the numerator.  Quotient	sign is Num.Sign xor* Denom.Sign*	lda Numerator	; Get num	pha	; put quot sign on stack	eor Denom	; eor with denom	pha	; push on stack* Now need absolute	values of operands	lda Numerator	bpl NoChange1	eor #$FFFF	inc a	sta NumeratorNoChange1	lda Denom	bpl NoChange2	eor #$FFFF	inc a	sta DenomNoChange2		; 	jsl UDIV	; do the divide	bcs ErrorExit	pla	; get quot sign	bpl NoChange3	lda Quotient	eor #$FFFF	inc a	sta QuotientNoChange3	pla	; get remainder sign	bpl NoChange4	lda Remainder	eor #$FFFF	inc a	sta RemainderNoChange4		; 	jmp EndCall4ErrorExit		; 	pla	; fix stack (added 9 Feb 87 by SEG)	pla	ldx #BadParam	jmp ErrOut4	ENDP****************************************************************** UDIV** This is called by	both UDivide and SDivide to do the actual* dividing.  The XRegister points to variables in the current* data bank (0).*****************************************************************	EXPORT UDIVUDIV	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Denom	equ RTL2+3Numerator	equ Denom+2Quotient	equ Numerator+2Remainder	equ Quotient+2	stz Quotient+2	; Zero high result	lda Denom	; Divide by zero ?	bne GoOn	; Nope	sec	; divide by zero *	rtlGoOn		; 	lda Numerator	; move numerator into	sta Quotient	; Result	ldy #16	sec	; set this to start?DivLoop	rol Quotient	rol Quotient+2	sec	lda Quotient+2	sbc Denom	bcc DecCt	sta Quotient+2DecCt	dey	bne DivLoop	rol Quotient	; Shift last carry through for Quot	clc	rtl	ENDP****************************************************************** LongMul** Multiplies two values on the stack.* Is called with a JSL after pushing the values and result onto* the stack.** Value returned is	in place of inputs.* Low word is the signed result of multiplication.* Two words together is the unsigned 32	bit result.** The stack looks like this:**      Result  12-19*      M1      8-11*      M2      4-7*      Return  1-3*****************************************************************	EXPORT LongMulLongMul	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3M2	equ RTL2+3M1	equ M2+4LResult	equ M1+4	phd	tsc	tcd	stz LResult+4	; zero the high words of	stz LResult+6	; the result	lda M2	sta LResult	lda M2+2	sta LResult+2	ldy #33	; number of bits in	multiplier + 1	clcMulLp	ror LResult+6	ror LResult+4	ror LResult+2	ror LResult	bcc DecCnt	clc	lda M1	adc LResult+4	sta LResult+4	lda M1+2	adc LResult+6	sta LResult+6DecCnt	dey	bne MulLp	jmp EndCall8	ENDP****************************************************************** LongDiv** Stack Looks Like:**    Remainder   16-19*    Quotient    12-15*    Numerator   8-11*    Denom       4-7*    Return      1-3*****************************************************************	EXPORT LongDivLongDiv	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3LDenom	equ RTL2+3LNum	equ LDenom+4LQuot	equ LNum+4LRem	equ LQuot+4	phd	; save direct register	tsc	; get stack pointer	tcd	; set direct register	lda LNum	; move numerator into	sta LQuot	; Result	lda LNum+2	sta LQuot+2	stz LQuot+4	; zero high result	stz LQuot+6	lda LDenom	ora LDenom+2	bne GoOn0	sec	; divide by zero *	bra Done0GoOn0		; 	ldy #32	sec	; set this to start?DivLp	rol LQuot	rol LQuot+2	rol LQuot+4	rol LQuot+6	sec	lda LQuot+4	sbc LDenom	tax	lda LQuot+6	sbc LDenom+2	bcc DecrCnt	sta LQuot+6	stx LQuot+4DecrCnt	dey	bne DivLp	rol LQuot	; Shift carry through for Quot	rol LQuot+2	jmp EndCall8Done0		; 	ldx #BadParam	jmp ErrOut8	ENDP****************************************************************** FixRatio** Takes two integers and returns a fixed** The stack is as follows when the function is called:**     Space for Result*     Numerator*     Denom** The FixRatio consists of two words:*     High Word = Numerator DIV Denom*     Low word  = (Numerator MOD Denom)	* 2^16 DIV Denom*** Change History** August 7, 1986	    Bug when result	was negative fixed by*	    Kenton Hanson.******************************************************************	EXPORT FixRatioFixRatio	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Denom	equ RTL2+3Numerator	equ Denom+2Result	equ Numerator+2	phd	; save the direct register	tsc	; get stack pointer	tcd	; put it in direct register	lda Denom	; check for div by zero	bne GoOnx	lda #$7FFF	sta Result+2	bra TheEndGoOnx	eor Numerator	; determine sign of	pha	; high bit is sign	pea 0	; push space for result	pea 0	lda Numerator	bpl NumPos	eor #$FFFF	inc aNumPos	pha	lda Denom	bpl DenPos	eor #$FFFF	inc aDenPos	pha	_UDivide	pla	; get result of unsigned divide	sta Result+2	; to zero page	plx	; get remainder in x	pea 0	; make room for result of	pea 0	; long divide	pea 0	pea 0	phx	; put remainder * 2^16 on stack	pea 0	pea 0	lda Denom	bpl Pos2	eor #$FFFF	inc aPos2	pha	_LongDivide	pla	; get low word of result	sta Result	;	pla	; ignore high word	pla	; ignore remainder	pla	pla	; get sign off stack	bpl TheEnd	; NoInversion	lda #0	;<klh, 17Jul86, was	#1>	sec	sbc Result	sta Result	lda #0	sbc Result+2	sta Result+2TheEnd		; 	jmp EndCall4	ENDP;                copy intmath/math2****************************************************************** FUNCTION FixMul (x, y: Fix): Fix;* FUNCTION FracMul (x, y: Fract): Fract;** Multiplies two values on the stack.* Is called with a JSL after pushing the values and result onto* the stack.** FUNCTION FixDiv (x, y: Fix): Fix;* FUNCTION FracxDiv	(x, y: Fract): Fract;** Same as FracMul, except returns x divided by y** The stack looks like this on input:**      Result	 C-F*      M1	 8-B*      M2	 4-7*      Return	 1-3*****************************************************************	EXPORT FixDivFixDiv	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3M2	equ RTL2+3M1	equ M2+4Result	equ M1+4	ldy #16	bra FMulDiv	EXPORT FracDivFracDiv		;       	ldy #30	bra FMulDiv	EXPORT FixMulFixMul		;       	ldy #0	bra FMulDiv	EXPORT FracMulFracMul		;       	ldy #-31FMulDiv	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	stz Result	; zero the Result	stz Result+2	lda M1+2	eor M2+2	pha	; push eor of signs	onto stack	lda M1+2	bpl bplM1	lda #00	sec	sbc M1	sta M1	lda #00	sbc M1+2	sta M1+2bplM1	lda M2+2	bpl MDSwtch	lda #00	sec	sbc M2	sta M2	lda #00	sbc M2+2	sta M2+2MDSwtch	tya	bne NotFxMul	ldy #32	; note a := 0fxLoop	asl Result	rol Result+2	rol a	bmi fixOver	rol M2	rol M2+2	bcc decIt	tax	; save a	clc	lda M1	adc Result	sta Result	lda M1+2	adc Result+2	sta Result+2	txa	; restore a	bcc decIt	inc a	bmi fixOverdecIt	dey	bne fxLoop	asl Result	; sets carry for bcs below	ldx Result+2	stx Result	sta Result+2	bcs Rnding	; round up	bcc ChkSign	; no rounding, check sign of outputNotFxMul	bpl GoDvdMulLoop	lsr Result+2	ror Result	ror M2+2	ror M2	bcc DecCount	clclastAdd	lda M1	adc Result	sta Result	lda M1+2	adc Result+2	sta Result+2DecCount	iny	bmi MulLoop	bne roundIt	lsr M2	bcc roundIt	asl M1	;align M1 for the final add	rol M1+2	bcc lastAddfixOver	stz Result	;fix overflow	lda #$8000	sta Result+2	pla	;get sign of result	bmi finMul	dec Result	dec Result+2	bra finMulroundIt	bit M2+2	bpl NoRndingRnding	inc Result	bne NoRnding	inc Result+2NoRnding	bit Result+2	bmi fixOverChkSign	pla	bpl finMul	lda #00	sec	sbc Result	sta Result	lda #00	sbc Result+2	sta Result+2finMul		; 	jmp EndCall8GoDvd	lda M1	sta Result	stz M1	lda M1+2	sta Result+2	stz M1+2	phy	;save y	ldy #32	clcDvLoop1	rol Result	rol Result+2	rol M1	rol M1+2	sec	lda M1	sbc M2	tax	lda M1+2	sbc M2+2	bcc NoGo1	sta M1+2	stx M1NoGo1	dey	bne DvLoop1	ply	;restore yDvLoop2	rol Result	rol Result+2	bmi fixOver	;result overflowed	rol M1	rol M1+2	sec	lda M1	sbc M2	tax	lda M1+2	sbc M2+2	bcc NoGo2	sta M1+2	stx M1NoGo2	dey	bpl DvLoop2	bcs Rnding	; round result	bcc ChkSign	; no rounding	ENDP****************************************************************** PROCEDURE Fix2X (f: Fixed; var x: Extended );* PROCEDURE Frac2X (f: Fract; var x: Extended );**    Note:  Assumes	Extended numbers are normalized** The stack looks like this on input:**      Fixed or Frac 8-B*      A2	 4-7	;address of an Extended*      Return	 1-3*****************************************************************	EXPORT Fix2XFix2X	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3A2	equ RTL2+3M1	equ A2+4	ldx #$400e	; threshold extended exponent for Fixed	bra F2X	EXPORT Frac2XFrac2X		;       	ldx #$4000	; threshold extended exponent for FractF2X	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	lda #0	tay	sta [<A2],y	iny	iny	sta [<A2],y	iny	iny	lda M1+2	pha	; save sign	bpl ZeroChk	lda #00	sec	sbc M1	sta M1	lda #00	sbc M1+2	sta M1+2	bra NrmlZeroChk	bne Nrml	lda M1	bne NLoop	; begin normalization	sta [<A2],y	iny	iny	sta [<A2],y	iny	iny	sta [<A2],y	pla	; pull sign of stack	bra FinF2XNLoop	dex	; decrement exponent	asl M1	rol M1+2Nrml	bpl NLoop	lda M1	sta [<A2],y	; set least signficant word of Fixed	iny	iny	lda M1+2	sta [<A2],y	; set most signficant word of Fixed	iny	iny	pla	; get sign from stack	sta M1+2	txa	; put exponent into	a	asl a	asl M1+2	; get sign into carry	ror a	; shift sign into a	sta [<A2],y	; set exponent and signfinF2X		; 	jmp EndCall8	ENDP****************************************************************** FUNCTION FixRound	(f: fixed): integer;** The stack looks like this on input:**      Result	 8-9*      A1	 4-7*      Return	 1-3*****************************************************************	EXPORT FixRoundFixRound	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3A1	equ RTL2+3Result	equ A1+4	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	ldx A1+2	stx Result	lda A1	bpl FinFxRnd	; no rounding bit, done	inx	cpx #$8000	beq FinFxRnd	; overflow, do not round up	stx ResultFinFxRnd		; 	jmp EndCall4	ENDP****************************************************************** FUNCTION FracSqrt	(x: Fract): Fract;** Square root of x.	 In this case, the leading two bits of Fract are BOTH* taken to be integer, that is, the value is interpreted as	unsigned.** The stack looks like this on input:**      Result	 8-B*      M1	 4-7*      Return	 1-3*****************************************************************	EXPORT FracSqrtFracSqrt	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3M1	equ RTL2+3Result	equ M1+4mask	equ Resultmask2	equ M1	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	stz Result+2	sec	lda M1+2	sbc #$4000	bcc LtOne	sta M1+2	lda #$4000	sta Result+2LtOne	lda #$1000	; initialize mask	sta maskRootLoop	sec	lda M1+2	sbc Result+2	bcc NoGo	sbc mask	bcc NoGo	sta M1+2	; subtract succeeded, save result	clc	lda Result+2	adc mask	; update Result	adc mask	sta Result+2NoGo	asl M1	rol M1+2	lsr mask	bcc RootLoop	lda M1	tax	; M1 will now be stored in x	stz mask2	; location of M1 now used for mask2	ror mask2SqrtLoop	sec	sbc Result	tay	; save low intermediate result	lda M1+2	sbc Result+2	bcc NoGos	; does not divide	pha	; store hi result temp on stack	tya	sbc mask2	; subtract mask	tay	pla	; restore hi result	from stack	sbc #$0000	bcc NoGos	; subtraction caused negative value	sta M1+2	; subtract succeeded, save result	tyx	; sty M1, that is, x	clc	lda Result	adc mask2	; update Result	adc mask2	sta Result	bcc NoGos	inc Result+2NoGos	txa	asl a	tax	rol M1+2	lsr mask2	bcc SqrtLoop	sec	; need two more bits	sbc Result	tay	; save low intermediate result	lda M1+2	sbc Result+2	bcc ToGos	; does not divide	pha	; store hi result temp on stack	lda mask2	; lda 0	sbc #$8000	; subtract mask	tya	sbc mask2	; subtract 0	tay	pla	; restore hi result	from stack	sbc mask2	; subtract 0	bcc ToGos	; subtraction caused negative value	sta M1+2	; subtract succeeded, save result	tyx	; sty M1, that is, x	inc Result	bne ToGos	inc Result+2ToGos	txa	rol a	; Note carry is set	iff subtraction	rol M1+2	; was successful	sec	; determine round bit	sbc Result	tay	; save low intermediate result	lda M1+2	sbc Result+2	bcc EndSqrt	; does not divide	pha	; store hi result temp on stack	lda mask2	sbc #$4000	; subtract last mask	tya	sbc mask2	; subtract 0	pla	; restore hi result	from stack	sbc mask2	; subtract 0	bcc EndSqrt	; subtraction caused negative value	inc Result	bne EndSqrt	inc Result+2EndSqrt		; 	jmp EndCall4	ENDP****************************************************************** FUNCTION FracCos (x: Fixed): Fixed;* FUNCTION FracSin (x: Fixed): Fixed;** Returns the Cos or Sin of argument (radians)** The stack looks like this on input:**      Result	 8-B*      M1	 4-7*      Return	 1-3*****************************************************************	EXPORT FracCosFracCos	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3M1	equ RTL2+3Result	equ M1+4	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	ldx #2	bit M1+2	bmi Negate	bpl Reduce	EXPORT FracSinFracSin		;       	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	ldx #0	bit M1+2	bpl Reduce	ldx #4Negate	sec	lda #00	sbc M1	sta M1	lda #00	sbc M1+2	sta M1+2Reduce	ldy #$10	;16 bits of division necessaryRemLoop	sec	lda M1+2	sbc #$6488	;PI/2 (when shifted	14 bits to right)	bmi tooLarge	sta M1+2tooLarge	rol M1	;shift in result	rol M1+2	dey	bne RemLoop	clc	txa	adc M1	; remainder + phase	shift	pha	; save on stack	lsr a	bcc at4	lda #$c910	; M1 := PI/4 - M1	sbc M1+2	sta M1+2at4	stz M1	lsr M1+2	; Fixed to Frac	ror M1	lsr M1+2	ror M1	lsr M1+2	ror M1	pha	; push space for return result sqr(x/2)	pha	pei M1+2	pei M1	pei M1+2	pei M1	_FracMul	ply	; x2 := (x/2)^2	sty Result	plx	stx Result+2	pla	; get phase shift	pha	inc a	and #$0002	bne Cos	pha	; x2*sn2	pha	phx	phy	pea $10A2	pea $08E5	_FracMul	clc	; sn1 + x2*sn2	pla	adc #$314D	tay	pla	adc #$AAB3	pha	; x2*(sn1 + x2*sn2)	pha	pha	phy	pei Result+2	pei Result	_FracMul	clc	; sn0 + x2*(xn1 + x2*sn2)	pla	adc #$D609	tay	pla	adc #$7FFF	pha	; (x/2)*(sn0 + x2*(sn1 + x2*sn2))	pha	pha	phy	pei M1+2	pei M1	_FracMul	ply	sty Result	plx	stx Result+2	bra ckSignCos	pha	; x2*cs3	pha	phx	phy	pea $FA6E	pea $2A42	_FracMul	clc	; cs2 + x2*cs3	pla	adc #$F29A	tay	pla	adc #$2AA7	pha	; x2*(cs2 + x2*cs3)	pha	pha	phy	pei Result+2	pei Result	_FracMul	clc	; cs1 + x2*(cs2 + x2*cs3)	pla	adc #$11A7	tay	pla	adc #$8000	pha	; x2*(cs1 + x2*(cs2	+ x2*cs3))	pha	pha	phy	pei Result+2	pei Result	_FracMul	clc	; 1.0 + x2*(cs1 + x2*(cs2 + x2*cs3))	pla	sta Result	pla	adc #$4000	sta Result+2ckSign	pla	; retrieve phase shift	and #$0004	beq EndCsSn	sec	lda #$0000	sbc Result	sta Result	lda #$0000	sbc Result+2	sta