pla	adc #$3FFF	pha	pha	pha	phy	pei M2+2	pei M2	_FracMul	pla	; get result	ply	sty Result	asl a	; Frac2Fix	rol Result	rol Result+2	asl a	rol Result	rol Result+2	asl a	bcc noRnd	; check for rounding	inc Result	bne noRnd	inc Result+2noRnd	pla	; get reduction information from stack	asl a	sta M1	bcs at2	; |x| <= |y|	lda #$9220	; Result := PI/2 - Result	sbc Result	sta Result	lda #$0001	sbc Result+2	sta Result+2at2	asl M1	bcc at1	; x was postive	lda #$2440	; Result := PI - Result	sbc Result	sta Result	lda #$0003	sbc Result+2	sta Result+2at1	asl M1	bcc EndATan2	; y was postive	lda #$0000	sbc Result	; Result := -Result	sta Result	lda #$0000	sbc Result+2	sta Result+2EndAtan2		; 	jmp EndCall8*        sn0     DC	     H'09 d6 ff 7f'*                DC	     H'4d 31 b3 aa'*                DC	     H'e5 08 a2 10'*        cs0     DC	     H'00 00 00 40'*                DC	     H'a7 11 00 80'*                DC	     H'9a f2 a7 2a'*                DC	     H'42 2a 6e fa'*        at0     DC	     H'73 a0 ff 3f'*                DC	     H'be 4e b6 ea'*                DC	     H'2c f7 62 0c'*                DC	     H'f2 77 8c f8'*                DC	     H'fe 92 5e 03'*                DC	     H'62 fe 3f ff'	ENDP****************************************************************** FUNCTION HiWord (l: long): integer;* FUNCTION LoWord (l: long): integer;** The stack looks like this on input:**      Result	 8-9*      A1	 4-7*      Return	 1-3*****************************************************************	EXPORT HiWordHiWord	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3A1	equ RTL2+3Result	equ A1+4	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	lda A1+2	bra StuffInt	EXPORT LoWordLoWord		;       	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	lda A1StuffInt	sta Result	jmp EndCall4	ENDP****************************************************************** FUNCTION Long2Fix	(l: long): Fixed;* FUNCTION Fix2Frac	(f: Fixed): Fract;** The stack looks like this on input:**      Result	 8-B*      A1	 4-7*      Return	 1-3*****************************************************************	EXPORT Long2FixLong2Fix	PROCDReg	equ 1RTL1	equ DReg+2RTL2	equ RTL1+3A1	equ RTL2+3Result	equ A1+4	ldx #15	bra ShftLeft	EXPORT Fix2FracFix2Frac		;       	ldx #13ShftLeft	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	lda A1	sta Result	lda A1+2	sta Result+2	pha	; save sign	bpl Xloop	lda #00	sec	sbc Result	sta Result	lda #00	sbc Result+2	sta Result+2	bmi MaxIt	; overflow occurredXloop	asl Result	rol Result+2	bmi MaxIt	; overflow has occurred	dex	; decrement counter	bpl Xloop	bra ChkSign****************************************************************** FUNCTION Fix2Long	(f: Fixed): long;* FUNCTION Frac2Fix	(f: Fract): Fixed;** The stack looks like this on input:**      Result	 8-B*      A1	 4-7*      Return	 1-3*****************************************************************	EXPORT Fix2longFix2long		;       	ldx #15	bra ShftRght	EXPORT Frac2FixFrac2Fix		;       	ldx #13ShftRght	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	lda A1	sta Result	lda A1+2	sta Result+2	pha	; save sign	bpl Rloop	lda #00	sec	sbc Result	sta Result	lda #00	sbc Result+2	sta Result+2Rloop	txa	bra ShftloopMaxIt	stz Result	;fix overflow	lda #$8000	sta Result+2	pla	;get sign of result	bmi finX2F	dec Result	dec Result+2	bra finX2FZeroIt	stz Result	stz Result+2	pla	; take sign off stack	bra finX2F****************************************************************** FUNCTION X2Fix (x: Extended ): Fixed;* FUNCTION X2Frac(x: Extended ): Fract;**    Note:  Assumes	Extended numbers are normalized** The stack looks like this on input:**      Result	 8-B*      A1	 4-7	;address of an Extended*      Return	 1-3*****************************************************************	EXPORT X2FixX2Fix		;       	ldx #$400e	; threshold extended exponent for Fixed	bra X2F	EXPORT X2FracX2Frac		;       	ldx #$4000	; threshold extended exponent for FractX2F	phd	; save direct reg	tsc	; set direct reg to	tcd	; point to place on	stack	ldy #4	lda [<A1],y	; get least signficant word of Fixed	sta Result	iny	iny	lda [<A1],y	; get most signficant word of Fixed	sta Result+2	iny	iny	lda [<A1],y	; get exponent and sign	pha	; push sign onto stack	and #$7fff	; strip sign	sta A1	txa	clc	sbc A1	bmi MaxIt	; either a NaN, Inf	or too large a value	cmp #33	bpl ZeroIt	; even MSB shifted too far to cause rndShftloop	lsr Result+2	ror Result	dec a	bpl Shftloop	bcc NoRndingroundIt	inc Result	bne NoRnding	inc Result+2NoRnding	bit Result+2	bmi MaxItChkSign	pla	bpl finX2F	lda #00	sec	sbc Result	sta Result	lda #00	sbc Result+2	sta Result+2finX2F		; 	jmp EndCall4	ENDP;                copy intmath/binhex****************************************************************** Int2Hex** Takes a 2-byte unsigned integer and produces an ASCII string* representing the value in hexadecimal	format.*****************************************************************	EXPORT Int2HexInt2Hex	PROCTempVal	equ 1BinVal	equ 19	phd	PushWord #0	;temp space	PushWord #0	tsc	tcd	lda <BinVal	;move value into temp space	sta <TempVal	jsr Bin2Hex	pla	;pull temp space	pla	cpx #0	;was there an error?	bne RetErr	;yes	jmp EndCall8RetErr	jmp ErrOut8	ENDP****************************************************************** Long2Hex** Takes a 4-byte unsigned integer and produces an ASCII string* representing the value in hexadecimal	format.*****************************************************************	EXPORT Long2HexLong2Hex	PROCTempVal	equ 1BinVal	equ 19	phd	PushWord #0	;temp space	PushWord #0	tsc	tcd	lda <BinVal	;move value into the temp space	sta <TempVal	lda <BinVal+2	sta <TempVal+2	jsr Bin2Hex	pla	;pull temp space	pla	cpx #0	;was there an error?	bne RetErr	;yes	jmp EndCall10RetErr	jmp ErrOut10	ENDP****************************************************************** Bin2Hex*****************************************************************	EXPORT Bin2HexBin2Hex	PROCTempVal	equ 1Length	equ 13StrPtr	equ 15	ldy <Length	;index into stringLoop	dey	;done with string?	bmi Done	;yes	lda <TempVal	and #$F	;get lowest nibble of value	jsr MakeChar	;make into an ASCII	char	sep #$30	;8 bit mode	sta [<StrPtr],y	;put char in string	rep #$30	;16 bit mode	ldx #4Shift	lsr <TempVal+2	;shift value to right by 4 bits	ror <TempVal	dex	bne Shift	bra LoopDone	lda <TempVal	;have we converted the whole value?	ora <TempVal+2	bne StrErr	;no - so string was	too short	ldx #0	;no error	rtsStrErr	ldx #ShortStr	rtsMakeChar	cmp #$A	bcc Cont	clc	;add 7 so when convert to ASCII the	adc #7	;values 10-15 become A-FCont	adc #$30	;convert value to an ASCII char	rts	ENDP;                copy intmath/hexbin****************************************************************** Hex2Int** Takes an ASCII string representing a hexadecimal value and* produces a 2-byte	unsigned integer.*****************************************************************	EXPORT Hex2IntHex2Int	PROCBinVal	equ 21	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	jsr Hex2Bin	pla	;pull result	sta <BinVal	pla	;overflow?	bne OverErr	;yes	plx	;error flag	bne RetErr	jmp EndCall6OverErr	ldx #Overflow	pla	;error flagRetErr	jmp ErrOut6	ENDP****************************************************************** Hex2Long** Takes an ASCII string representing a hexadecimal value and* produces a 4-byte	unsigned integer.*****************************************************************	EXPORT Hex2LongHex2Long	PROCBinVal	equ 21	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	jsr Hex2Bin	pla	;pull result	sta <BinVal	pla	sta <BinVal+2	plx	;error flag	bne RetErr	jmp EndCall6RetErr	jmp ErrOut6	ENDP****************************************************************** Hex2Bin*****************************************************************	EXPORT Hex2BinHex2Bin	PROCTempVal	equ 1Digit	equ 5Length	equ 15StrPtr	equ 17	ldy #0	;string index	ldx #0	;overflow flag	deyBlanks	iny	cpy <Length	;end of string?	bcs Return	;yes	lda [<StrPtr],y	;skip leading blanks in string	and #$7F	;mask off hi byte and hi bit of lo byte	cmp #$20	beq BlanksLoop	cpy <Length	;end of string?	bcs Done	;yes	lda [<StrPtr],y	;get char from string	and #$7F	;mask off hi byte and hi bit of lo byte	jsr MakeBin	;convert to binary nibble	sta <Digit	;and save	lda <TempVal+2	cmp #$1000	;will overflow occur?	bcc Cont	;no	inx	;yes - so flag itCont	asl <TempVal	;shift value over by 4 bits	rol <TempVal+2	asl <TempVal	rol <TempVal+2	asl <TempVal	rol <TempVal+2	asl <TempVal	rol <TempVal+2	lda <TempVal	ora <Digit	;add in digit	sta <TempVal	iny	bra LoopDone	cpx #0	;did overflow occur?	beq Return	;no	ldx #Overflow	;yes - so set error	numberReturn	stx <Digit	;store error	rtsMakeBin	cmp #$3A	;is char < ':' ?	bcc OK	;yes	cmp #$47	;is char < 'G' ?	bcc UC	;yes	cmp #$67	;is char > 'f' ?	bcs CharErr	;yes	sec	sbc #$20	;convert to upper caseUC	cmp #$41	;is char < 'A' ?	bcc CharErr	;yes	sbc #7	;char is in 'A' - 'F'OK	sec	sbc #$30	;convert char to binary value	bcc CharErr	;char was < '0'	rtsCharErr	pla	;pull return address off stack	ldx #BadChar	jmp Return	ENDP;                copy intmath/bindec****************************************************************** Int2Dec** Takes a 2-byte integer (signed or unsigned) and produces an* ASCII string representing the value in decimal format.*****************************************************************	EXPORT Int2DecInt2Dec	PROCTempVal	equ 1Digit	equ 5Signed	equ 15Length	equ 17StrPtr	equ 19BinVal	equ 23	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	ldy <Length	;index into string	lda <BinVal	;move value into temp space	sta <TempVal	bpl Loop	;branch if value is	positive	lda <Signed	;is value signed?	beq Loop	;no - so skip next part	sec	lda #0	;value is negative so change it to	sbc <TempVal	;positive	sta <TempValLoop	dey	bmi StrErr	;done with string;		;TempVal := TempVal	DIV 10;		;Digit   := TempVal	MOD 10	stz <Digit	ldx #16	;size of data in bits	clcDivLoop	rol <TempVal	;shift carry into dividend bit 0 which	rol <Digit	;will be the quotient and shift dividend	sec	;at the same time	lda <Digit	sbc #10	;A := dividend - divisor	bcc DecCnt	;branch if dividend	< divisor	sta <Digit	;dividend := dividend - divisorDecCnt	dex	bne DivLoop	rol <TempVal	;shift in the last carry for the quotient	lda <Digit	;convert digit into	ASCII char	clc	adc #$30	sep #$30	;8 bit mode	sta [<StrPtr],y	;put char in string	rep #$30	;16 bit mode	lda <TempVal	;is value 0?	bne Loop	;no - so continue	lda <Signed	;is value signed?	beq Cont	;no	lda <BinVal	;was original value	negative?	bpl Cont	;no	dey	;room for '-' in front of string?	bmi StrErr	;no	lda #$2D	;put '-' in front of string	sep #$30	;8 bit mode	sta [<StrPtr],y	rep #$30	;16 bit modeCont	dey	;is string filled?	bmi Done	;yes	LONGA off	LONGI off	sep #$30	;8 bit modeFill	lda #$20	;fill beginning of string with blanks	sta [<StrPtr],y	dey	bpl Fill	rep #$30	;16 bit mode	LONGA on	LONGI onDone	pla	;temp space	pla	pla	jmp EndCall10StrErr	ldx #ShortStr	pla	;temp space	pla	pla	jmp ErrOut10	ENDP****************************************************************** Long2Dec** Takes a 4-byte integer (signed or unsigned) and produces an* ASCII string representing the value in decimal format.** Change History** 30 Mar 89	Steven Glass** Long2Dec stoped converting as soon as all the bits in the * low 3 bytes were zero.  This was reported on 37 Mar 89 by * Dave Tribby (an outside developer using UseNet).* * Dave debugged the code for us using NiftyList and found * a lda Val, ora Val+1 that should have been ora Val+2.  * Thanks Dave.*****************************************************************	EXPORT Long2DecLong2Dec	PROCTempVal	equ 1Digit	equ 5Signed	equ 15Length	equ 17StrPtr	equ 19BinVal	equ 23	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	ldy <Length	;index into string	lda <BinVal	;copy value into temp space	sta <TempVal	lda <BinVal+2	sta <TempVal+2	bpl Loop	;branch if value is	positive	lda <Signed	;is value signed?	beq Loop	;no - so skip next part	sec	lda #0	;convert value to positive	sbc <TempVal	sta <TempVal	lda #0	sbc <TempVal+2	sta <TempVal+2Loop	dey	bmi StrErr	;done with string;		;TempVal := TempVal	DIV 10;		;Digit   := TempVal	MOD 10	stz <Digit	ldx #32	;size of data in bits	clcDivLoop	rol <TempVal	;shift the carry into dividend bit 0	rol <TempVal+2	;which will be the quotient and	rol <Digit	;shift the dividend	at the same time	sec	lda <Digit	;A := dividend - divisor	sbc #10	bcc DecCnt	;branch if dividend	< divisor	sta <Digit	;dividend := dividend - divisorDecCnt	dex	bne DivLoop	rol <TempVal	;shift in the last carry for the quotient	rol <TempVal+2	lda <Digit	;convert digit to ASCII char	clc	adc #$30	sep #$30	;8 bit mode	sta [<StrPtr],y	rep #$30	;16 bit mode	lda <TempVal	ora <TempVal+2	;is value 0?	##### changed to +2, 30 Mar 89 SEG	bne Loop	;no - so continue	lda <Signed	;is value signed?	beq Cont	;no	lda <BinVal+2	;was original value	negative?	bpl Cont	;no	dey	;room for '-' in front of string?	bmi StrErr	;no	lda #$2D	;put '-' in front of string	sep #$30	;8 bit mode	sta [<StrPtr],y	rep #$30	;16 bit modeCont	dey	;is string filled?	bmi Done	;yes	LONGA off	LONGI off	sep #$30	;8 bit modeFill	lda #$20	;fill beginning of string with blanks	sta [<StrPtr],y	dey	bpl Fill	rep #$30	;16 bit mode	LONGA on	LONGI onDone	pla	;temp space	pla	pla	jml EndCall12StrErr	ldx #ShortStr	pla	;temp space	pla	pla	jml ErrOut12	ENDP****************************************************************** Dec2Int** Takes an ASCII string representing a decimal value and* produces a 2-byte	signed or unsigned integer.*****************************************************************	EXPORT Dec2IntDec2Int	PROCSigned	equ 15BinVal	equ 23	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	jsr Dec2Bin	pla	;pull result	sta <BinVal	pla	;did result overflow ?	bne OverErr	;yes	lda <Signed	;is value signed?	beq OK	;no - so skip next part	lda <BinVal	cmp #$8000	;check for maximum negative number	bne Cont	cpy #0	;was the sign negative ?	bne OK	;yesCont	asl a	;is hi bit set?	bcs OverErr	;yes - so overflowOK	plx	;pull error flag	bne RetErr	tya	;sign flag	beq Done	sec	;sign was negative so change	lda #0	;result to a negative value	sbc <BinVal	sta <BinValDone	jmp EndCall8OverErr	ldx #Overflow	pla	;error flagRetErr	jmp ErrOut8	ENDP****************************************************************** Dec2Long** Takes an ASCII string representing a decimal value and* produces a 4-byte	signed or unsigned integer.*****************************************************************	EXPORT Dec2LongDec2Long	PROCSigned	equ 15BinVal	equ 23	phd	PushWord #0	;temp space	PushWord #0	PushWord #0	tsc	tcd	jsr Dec2Bin	pla	;pull result	sta <BinVal	pla	sta <BinVal+2	lda <Signed	;is value signed?	beq OK	;no - so skip next part	lda <BinVal+2	cmp #$8000	;check for maximum negative number	bne Cont	lda <BinVal	bne Cont	cpy #0	;was the sign negative?	bne OK	;yesCont	lda <BinVal+2	asl a	;is hi bit set?	bcs OverErr	;yes - so overflowOK	plx	;error flag	bne RetErr	tya	;sign flag	beq Done	sec	;sign was negative so change result	lda #0	;to negative value	sbc <BinVal	sta <BinVal	lda #0	sbc <BinVal+2	sta <BinVal+2Done	jmp EndCall8OverErr	ldx #Overflow	pla	;error flagRetErr	jmp ErrOut8	ENDP****************************************************************** Dec2Bin*****************************************************************	EXPORT Dec2BinDec2Bin	PROCTempVal	equ 1Digit	equ 5Signed	equ 15Length	equ 17StrPtr	equ 19BinVal	equ 23	ldy #0	;string index	ldx #0	;sign flag	deyBlanks	iny	cpy <Length	bcc OK	rtsOK	lda [<StrPtr],y	;skip leading blanks in string	and #$7F	;mask off hi byte and hi bit of lo byte	cmp #$20	beq Blanks	cpx <Signed	;is value signed?	beq Sign	;no - so skip next part	cmp #$2B	;is first char '+' ?	bne CheckNeg	;no	iny	;yes - so skip first char	bra SignCheckNeg	cmp #$2D	;is first char '-' ?	bne Sign	;no	iny	;yes - so skip first char	ldx #$FF	;flag negative signSign	phx	;save sign flag	ldx #0	;overflow flagLoop	cpy <Length	;done with string?	bcs Done	;yes	lda [<StrPtr],y	;get char	and #$7F	;mask off hi byte and hi bit of lo byte	cmp #$30	;is char < '0' ?	bcc CharErr	;yes	cmp #$3A	;is char > '9' ?	bcs CharErr	;yes	sec	sbc #$30	;convert char to digit	sta <Digit	;save digit	asl <TempVal	;mult val by 2	rol <TempVal+2	bcc Cont	inx	;set flag if overflowCont	lda <TempVal+2	sta <BinVal	;save hi word in BinVal	lda <TempVal	;save lo word in A	asl <TempVal	rol <TempVal+2	bcc Cont0	inx	;set flag if overflowCont0	asl <TempVal	rol <TempVal+2	;mult val by 8	bcc Cont1	inx	;set flag if overflow	clcCont1	adc <TempVal	;sum with val times	2	sta <TempVal	;to get val times 10	lda <BinVal	adc <TempVal+2	sta <TempVal+2	bcc Cont2	inx	;set overflow flag	clcCont2	lda <TempVal	adc <Digit	;add digit to val	sta <TempVal	bcc Cont3	lda <TempVal+2	adc #0	sta <TempVal+2	bcc Cont3	inx	;set overflow flagCont3	iny	bra LoopDone	cpx #0	;did overflow occur?	beq Return	;no	ldx #Overflow	;yesReturn	stx <Digit	;save error flag	ply	;sign flagDoRet	rtsCharErr	ldx #BadChar	jmp Return	ENDP;                copy intmath/hexit****************************************************************** HexIt      (value	: integer) : LongInt** The longint that is returned is made up of four* bytes that are the hex representation	of the word.** Calling Convention:**              PushLong #0	; make room on stack*              PushWord Whatever*              _HexIt*              PopLong Whereever*****************************************************************	EXPORT HexItHexIt	PROCRTL1	equ 1RTL2	equ RTL1+3Value	equ RTL2+3Result	equ Value+2	sep #%00110000	; 8 bit mode	longa off	longi off	lda Value,s	; get the low byte	and #$F0	; do the high nibble of low byte	lsr a	lsr a	lsr a	lsr a	jsr Nib2Ascii	sta Result+2,s	lda Value,s	; get the low byte back	and #$0F	; do the low nibble	of the low byte	jsr Nib2Ascii	sta Result+3,s	lda Value+1,s	; get the high byte	and #$F0	; do the high nibble	lsr a	lsr a	lsr a	lsr a	jsr Nib2Ascii	sta Result,s	lda Value+1,s	and #$0F	jsr Nib2Ascii	sta Result+1,s	rep #%00110000	longa on	longi on	jmp oEndCall2Nib2Ascii		; 	longa off	longi off	cmp #10	bcc Less10	clc	adc #7Less10	adc #$30	; ascii 0	rts	longa on	longi on	ENDP	END